## 实例

__说明：__ 获取数据库中所有的Player信息，并显示在页面上。

1. 整合Program.cs文件

```csharp
public class Program
{
    public static void Main(string[] args)
    {
        var builder = WebApplication.CreateBuilder(args);

        // 添加控制器和视图服务
        builder.Services.AddControllersWithViews();

        // 添加数据库上下文服务到依赖注入容器
        builder.Services.AddDbContext<DatabaseContext>(options =>
            options.UseSqlite(builder.Configuration.GetConnectionString("DefaultConnection")));

        // 注册数据库种子服务
        builder.Services.AddTransient<SeedData>();

        // 注册PlayerPageController到依赖注入容器
        builder.Services.AddScoped<PlayerPageController>();

        var app = builder.Build();

        // 配置HTTP请求管道，映射属性路由的控制器
        app.MapControllers();

        // 初始化数据库
        using (var scope = app.Services.CreateScope())
        {
            var dbContext = scope.ServiceProvider.GetRequiredService<DatabaseContext>();
            var seedata = scope.ServiceProvider.GetService<SeedData>();

            dbContext.Database.EnsureCreated();
            seedata.InitialData();
        }

        app.Run();
    }
}
```

2. 修改PlayerPageController.cs文件

