{
    private readonly DatabaseContext _dbContext;

    public PlayerPageController(DatabaseContext dbContext)
    {
        _dbContext = dbContext;
    }

    [Route("PlayerPage")]
    public IActionResult Index()
    {
        var players = _dbContext.Players;

        return View(players);
    }
}
